#include <ctype.h>
#include <errno.h>
#include <limits.h>
#include <stdio.h>
#include <stdlib.h>

int main(void)
{
    const char input[] = "  245 items";
    char *end = NULL;
    long value;

    errno = 0;
    value = strtol(input, &end, 10);

    if (end == input) {
        fputs("No digits were found.\n", stderr);
        return 1;
    }
    if (errno == ERANGE || value < INT_MIN || value > INT_MAX) {
        fputs("The number is outside the int range.\n", stderr);
        return 1;
    }
    while (isspace((unsigned char)*end) != 0) {
        ++end;
    }
    if (*end != '\0') {
        printf("Parsed value: %ld; remaining text: %s\n", value, end);
        return 0;
    }

    printf("Parsed value: %ld; no remaining text\n", value);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

static int compare_ints(const void *left, const void *right)
{
    int a = *(const int *)left;
    int b = *(const int *)right;

    if (a < b) {
        return -1;
    }
    if (a > b) {
        return 1;
    }
    return 0;
}

int main(void)
{
    int values[] = { 42, 7, 19, 7, 31 };
    const size_t count = sizeof values / sizeof values[0];
    const int key = 19;
    int *found;
    size_t i;

    qsort(values, count, sizeof values[0], compare_ints);

    for (i = 0U; i < count; ++i) {
        printf("%s%d", i == 0U ? "" : " ", values[i]);
    }
    putchar('\n');

    found = bsearch(&key, values, count, sizeof values[0], compare_ints);
    if (found != NULL) {
        printf("Found: %d\n", *found);
    } else {
        puts("Not found");
    }
    return 0;
}
